// project initialization
namespace SpriteKind {
    export const Key = SpriteKind.create()
    export const Artifact = SpriteKind.create()
}

let hasKey = false

info.setScore(0)
info.setLife(3)

// game set up
scene.setBackgroundImage(assets.image`3dBackgroundOutside`)
tiles.setCurrentTilemap(assets.tilemap`lockedMuseum`)

// player sprite 
let player = sprites.create(img`
    . f f f . f f f f . f f f .
    f f f f f c c c c f f f f f
    f f f f b c c c c b f f f f
    f f f c 3 c c c c 3 c f f f
    . f 3 3 c c c c c c 3 3 f .
    . f c c c c 4 4 c c c c f .
    . f f c c 4 4 4 4 c c f f .
    . f f f b f 4 4 f b f f f .
    . f f 4 1 f d d f 1 4 f f .
    . . f f d d d d d d f f . .
    . . e f e 4 4 4 4 e f e . .
    . e 4 f b 3 3 3 3 b f 4 e .
    . 4 d f 3 3 3 3 3 3 c d 4 .
    . 4 4 f 6 6 6 6 6 6 f 4 4 .
    . . . . f f f f f f . . . .
    . . . . f f . . f f . . . .
`, SpriteKind.Player)
player.setKind(SpriteKind.Player)
tiles.placeOnTile(player, tiles.getTileLocation(0, 6))
controller.moveSprite(player)
scene.cameraFollowSprite(player)

// key sprite
let keySprite = sprites.create(assets.image`key`, SpriteKind.Key)
tiles.placeOnRandomTile(keySprite, assets.tile`emptyTile`)

// artifact sprites
let artifactsAssetsArray = [assets.image`catArtifact`, assets.image`framedArtifact`,
assets.image`dinoArtifact`, assets.image`vaseArtifact`, assets.image`gemArtifact`]

function spawnArtifacts(artifactImage: Image, tileImage: Image) {
    let artifactSprite = sprites.create(artifactImage, SpriteKind.Artifact)
    tiles.placeOnRandomTile(artifactSprite, tileImage)
}

for (let i = 5; artifactsAssetsArray.length > 0; i--) {
    spawnArtifacts(artifactsAssetsArray.shift(), assets.tile`placementTile`)
}

// enemy sprites
function spawnEnemy() {
    let museumGuard = sprites.create(assets.image`guard`, SpriteKind.Enemy)
    tiles.placeOnRandomTile(museumGuard, assets.tile`placementTile`)
    museumGuard.setVelocity(randint(15, 40), randint(15, 40))
    museumGuard.setFlag(SpriteFlag.BounceOnWall, true)
}

for (let i = 0; i < 3; i++) {
    spawnEnemy()
}

// overlap events
sprites.onOverlap(SpriteKind.Player, SpriteKind.Key, function (sprite: Sprite, otherSprite: Sprite) {
    if (!hasKey) {
        hasKey = true
        sprites.destroy(otherSprite, effects.spray)
        music.play(music.melodyPlayable(music.baDing), music.PlaybackMode.UntilDone)
        game.showLongText("You found the key!", DialogLayout.Center)
        game.showLongText("Go back to the entrance to open the door!", DialogLayout.Center)
    }
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Artifact, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(otherSprite, effects.trail)
    music.play(music.melodyPlayable(music.baDing), music.PlaybackMode.UntilDone)
    info.changeScoreBy(1)
    if (info.score() == 5) {
        game.gameOver(true)
    }
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(otherSprite)
    music.play(music.melodyPlayable(music.smallCrash), music.PlaybackMode.UntilDone)
    info.changeLifeBy(-1)
    spawnEnemy()
})

// open door 
scene.onHitWall(SpriteKind.Player, function (sprite: Sprite, location: tiles.Location) {
    if (player.tileKindAt(TileDirection.Top, assets.tile`doorTile`) && hasKey) {
        openDoor()
    } else if (player.tileKindAt(TileDirection.Top, assets.tile`doorTile`) && !hasKey) {
        game.showLongText("Find the key to unlock the museum and enter!", DialogLayout.Center)
    }
})

function openDoor() {
    scene.setBackgroundImage(assets.image`3dBackgroundInside`)
    tiles.setCurrentTilemap(assets.tilemap`unlockedMuseum`)
    music.play(music.melodyPlayable(music.magicWand), music.PlaybackMode.UntilDone)
}

